package edu.college.employee.dsa;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.List;
class DataStructuresTest{@Test void listSupportsAllRequiredOperations(){var x=new SinglyLinkedList<Integer>();assertTrue(x.isEmpty());x.insert(1);x.insert(2);assertEquals(List.of(1,2),x.traverse());assertEquals(2,x.search(v->v==2));assertTrue(x.update(v->v==2,3));assertTrue(x.delete(v->v==1));assertEquals(List.of(3),x.traverse());assertTrue(x.delete(v->true));assertTrue(x.isEmpty());}@Test void stackLifoAndUnderflow(){var s=new LinkedStack<Integer>();assertTrue(s.isEmpty());s.push(1);s.push(2);assertEquals(2,s.peek());assertEquals(List.of(2,1),s.display());assertEquals(2,s.pop());assertEquals(1,s.pop());assertThrows(IllegalStateException.class,s::pop);s.push(3);s.clear();assertTrue(s.isEmpty());}@Test void queueFifoAndUnderflow(){var q=new LinkedQueue<Integer>();assertTrue(q.isEmpty());assertEquals(0,q.size());q.enqueue(1);q.enqueue(2);assertEquals(2,q.size());assertEquals(1,q.peek());assertEquals(1,q.dequeue());assertEquals(2,q.dequeue());assertTrue(q.isEmpty());assertEquals(0,q.size());assertThrows(IllegalStateException.class,q::dequeue);q.enqueue(3);assertEquals(3,q.peek());q.clear();assertTrue(q.isEmpty());}}
